#!/usr/bin/env bash
# Generates a local .env with RANDOM dev secrets (git-ignored). SYNTHETIC DATA ONLY.
# Usage: scripts/gen-dev-env.sh [--force]    (existing .env is kept unless --force)
# In CI the same variables are appended to $GITHUB_ENV (see .github/workflows/ci.yml).
set -euo pipefail
cd "$(dirname "$0")/.."

if [[ -f .env && "${1:-}" != "--force" ]]; then
  echo ".env already exists (use --force to regenerate)"
  exit 0
fi

rand_hex() { openssl rand -hex "${1:-18}"; }
rand_b64() { openssl rand -base64 "${1:-32}" | tr -d '\n'; }

umask 077
cat > .env <<EOF
# Generated by scripts/gen-dev-env.sh. Local dev only; never commit.
POSTGRES_PASSWORD=$(rand_hex)
DB_PASSWORD=\${POSTGRES_PASSWORD}
KEYCLOAK_ADMIN_PASSWORD=$(rand_hex)
HDIP_PW_INGESTOR1=$(rand_hex)
HDIP_PW_CLINICIAN1=$(rand_hex)
HDIP_PW_ANALYST1=$(rand_hex)
HDIP_PW_AUDITOR1=$(rand_hex)
PHI_ENCRYPTION_KEYS=k1:$(rand_b64 32)
PHI_ACTIVE_KEY_ID=k1
PHI_HMAC_KEY=$(rand_b64 32)
GRAFANA_ADMIN_PASSWORD=$(rand_hex)
EOF
echo "wrote .env"
